-- ============================================================
-- 1. Create table academy_data and set permissions
-- ============================================================
create table if not exists academy_data (
  collection text not null,
  id text not null,
  data jsonb not null default '{}'::jsonb,
  updated_at timestamp with time zone not null default timezone('utc'::text, now()),
  primary key (collection, id)
);

alter table academy_data enable row level security;
drop policy if exists "Allow all operations for anon" on academy_data;
create policy "Allow all operations for anon" on academy_data for all to public using (true) with check (true);
grant all on academy_data to anon, authenticated, service_role;

